<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('reports');require_once ROOT_PATH.'/includes/reporting.php';$pageTitle='Reporting Center';$activeMenu='reports';$type=$_GET['type']??'budget';$from=$_GET['from']??date('Y-01-01');$to=$_GET['to']??date('Y-m-d');$dept=(int)($_GET['department_id']??0);$valid=['budget','expense','sales','marketing','monthly'];if(!in_array($type,$valid,true))$type='budget';$report=build_report($type,$from,$to,$dept);$rows=$report['rows'];$headers=$rows?array_keys($rows[0]):[];require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Reporting Center</h1><p>Generate operational reports and export them to PDF, Excel or CSV.</p></div><button class="btn btn-light border no-print" onclick="window.print()"><i class="fa-solid fa-file-pdf me-2"></i>Print / PDF</button></div>
<div class="row g-3 mb-4 no-print"><?php $cards=['budget'=>['Budget Summary','fa-wallet'],'expense'=>['Expense Report','fa-receipt'],'sales'=>['Sales Performance','fa-chart-line'],'marketing'=>['Marketing ROI','fa-bullhorn'],'monthly'=>['Monthly Financial','fa-calendar-days']];foreach($cards as $k=>$v):?><div class="col-6 col-md"><a class="text-decoration-none" href="<?=e(url('reports/index.php?type='.$k.'&from='.$from.'&to='.$to))?>"><div class="kpi-card <?=$type===$k?'border-primary':''?>"><div class="kpi-icon blue mb-3"><i class="fa-solid <?=$v[1]?>"></i></div><strong class="text-dark"><?=e($v[0])?></strong></div></a></div><?php endforeach;?></div>
<div class="card-panel"><div class="card-head"><h2 class="section-title"><?=e($report['title'])?></h2><div class="d-flex gap-2 no-print"><a class="btn btn-sm btn-light border" href="<?=e(url('reports/export.php?format=csv&type='.$type.'&from='.$from.'&to='.$to.'&department_id='.$dept))?>"><i class="fa-solid fa-file-csv me-1"></i>CSV</a><a class="btn btn-sm btn-light border" href="<?=e(url('reports/export.php?format=excel&type='.$type.'&from='.$from.'&to='.$to.'&department_id='.$dept))?>"><i class="fa-solid fa-file-excel me-1"></i>Excel</a></div></div><div class="card-body"><form class="row g-2 align-items-end mb-4 no-print"><input type="hidden" name="type" value="<?=e($type)?>"><div class="col-md-3"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-3"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-3"><label class="form-label">Department</label><select class="form-select" name="department_id"><option value="0">All departments</option><?php foreach(departments() as $d):?><option value="<?=$d['id']?>" <?=$dept===$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Generate Report</button></div></form><div class="table-responsive"><table class="table data-table"><thead><tr><?php foreach($headers as $h):?><th><?=e($h)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $key=>$v):?><td><?php if(is_numeric($v)&&preg_match('/Amount|Budget|Expenses|Sales|Spending|Balance|Target/i',$key)):?><?=money($v)?><?php elseif(str_contains($key,'%')):?><?=number_format((float)$v,2)?>%<?php else:?><?=e((string)$v)?><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></div></div>
<?php require ROOT_PATH.'/includes/footer.php';?>
